package org.jsoup.parser;

import org.jsoup.helper.Validate;
import org.jsoup.internal.Normalizer;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.HashMap;
import java.util.Map;

public class TagTest {

    @Test
    public void getName_EmptyTag_ReturnsEmptyString() {
        String tagName = "";
        assertEquals("", Tag.valueOf(tagName).getName());
    }

    @Test
    public void getName_NonEmptyTag_ReturnsTagName() {
        String tagName = "div";
        assertEquals("div", Tag.valueOf(tagName).getName());
    }

    @Test
    public void normalName_CanonicalizeTagName() {
        String tagName = "<div>";
        assertEquals("div", Tag.normalName(tagName));
    }

    @Test
    public void normalName_UncanonicalizedString_ReturnsCanonicalizedVersion() {
        String tagName = "div";
        assertEquals("div", Tag.normalName(tagName));
    }

    @Test
    public void isBlock_AllowedTags_ReturnsTrue() {
        String tagName = "p";
        assertTrue(Tag.isBlock(tagName));
    }

    @Test
    public void isBlock_DisallowedTags_ReturnsFalse() {
        String tagName = "span";
        assertFalse(Tag.isBlock(tagName));
    }

    @Test
    public void formatAsBlock_AllowedTags_ReturnsTrue() {
        String tagName = "p";
        assertTrue(Tag.formatAsBlock(tagName));
    }

    @Test
    public void formatAsBlock_DisallowedTags_ReturnsFalse() {
        String tagName = "span";
        assertFalse(Tag.formatAsBlock(tagName));
    }

    @Test
    public void isInline_AllowedTags_ReturnsTrue() {
        String tagName = "img";
        assertTrue(Tag.isInline(tagName));
    }

    @Test
    public void isInline_DisallowedTags_ReturnsFalse() {
        String tagName = "div";
        assertFalse(Tag.isInline(tagName));
    }

    @Test
    public void isEmpty_EmptyTag_ReturnsTrue() {
        Tag tag = Tag.valueOf("");
        assertTrue(tag.isEmpty());
    }

    @Test
    public void isEmpty_NonEmptyTag_ReturnsFalse() {
        Tag tag = Tag.valueOf("div");
        assertFalse(tag.isEmpty());
    }

    @Test
    public void isSelfClosing_SelfClosingTags_ReturnsTrue() {
        String tagName = "img";
        assertTrue(Tag.isSelfClosing(tagName));
    }

    @Test
    public void isSelfClosing_NonSelfClosingTags_ReturnsFalse() {
        String tagName = "div";
        assertFalse(Tag.isSelfClosing(tagName));
    }

    @Test
    public void setSelfClosing_SelfClosingTag_SetsTrue() {
        Tag tag = Tag.valueOf("img");
        assertTrue(tag.setSelfClosing());
    }

    @Test
    public void setSelfClosing_NonSelfClosingTag_ReturnsFalse() {
        Tag tag = Tag.valueOf("div");
        assertFalse(tag.setSelfClosing());
    }

    @Test
    public void equalsEqualitiesTwoTags_ReturnsTrue() {
        String tagName1 = "div";
        String tagName2 = "div";
        assertTrue(new Tag(tagName1).equals(new Tag(tagName2)));
    }

    @Test
    public void equalsDoesNotEqualTwoDifferentTags_ReturnsFalse() {
        String tagName1 = "div";
        String tagName2 = "span";
        assertFalse(new Tag(tagName1).equals(new Tag(tagName2)));
    }

    @Test
    public void hashCodeReturnsSameHashCodesForEqualTags() {
        String tagName1 = "div";
        String tagName2 = "div";
        assertEquals(Tag.valueOf(tagName1).hashCode(), Tag.valueOf(tagName2).hashCode());
    }
}
